function constructAlarmAddressSpace(server, addressSpace, eventObjects, done) {
  const opcua = coreServer.choreCompact.opcua;
  const rootFolder = addressSpace.findNode("RootFolder");
  const namespace = addressSpace.getOwnNamespace();
  const Variant = opcua.Variant;
  const DataType = opcua.DataType;

  function flowVal(key, fallback) {
    var v = sandboxFlowContext.get(key);
    return (v === null || v === undefined) ? fallback : v;
  }

  function addStr(bname, nid, getter) {
    namespace.addVariable({
      organizedBy: rootFolder.objects,
      browseName: bname,
      nodeId: "ns=1;s=" + nid,
      dataType: "String",
      value: {
        get: function() {
          return new Variant({ dataType: DataType.String, value: String(getter() || "") });
        }
      }
    });
  }

  function addDbl(bname, nid, getter) {
    namespace.addVariable({
      organizedBy: rootFolder.objects,
      browseName: bname,
      nodeId: "ns=1;s=" + nid,
      dataType: "Double",
      value: {
        get: function() {
          return new Variant({ dataType: DataType.Double, value: Number(getter() || 0) });
        }
      }
    });
  }

  // Flat — all nodes directly under Objects, no subfolders
  addStr("run_state", "run_state",
    function() { return flowVal("run_state", ""); });

  addStr("main_comment", "main_comment",
    function() { return flowVal("main_comment", ""); });

  addDbl("power_on_time", "power_on_time",
    function() {
      return flowVal("power_on_time", 0);
      // return (v && v.display) ? v.display : "";
    });

  addDbl("auto_operation_time", "auto_operation_time",
    function() {
      return flowVal("auto_operation_time", 0);
      // return (v && v.display) ? v.display : "";
    });

  addDbl("cutting_time", "cutting_time",
    function() {
      return flowVal("cutting_time", 0);
      // return (v && v.display) ? v.display : "";
    });

  addDbl("lifetime_total", "lifetime_total",
    function() { return flowVal("lifetime_total", 0); });

  addDbl("actual_feedrate_mm_min", "actual_feedrate_mm_min",
    function() { return flowVal("actual_feedrate_mm_min", 0); });

  addDbl("actual_spindle_rpm", "actual_spindle_rpm",
    function() { return flowVal("actual_spindle_rpm", 0); });

  node.warn("FANUC OPC UA address space ready");
  done();
}
